exhibit.text:
param vmSize 'Standard_D2s_v5' | 'Standard_D4s_v5'

resource vm 'Microsoft.Compute/virtualMachines@2024-07-01' = {
  name: 'vm-prod-01'
  location: 'eastus'
  properties: {
    hardwareProfile: {
      vmSize: vmSize
    }
  }
}

@allowed([
  'Standard_D2s_v5'
  'Standard_D4s_v5'
])
output deployedSize string = vmSize

# main.bicep
param location string = 'westeurope'
param prefix string = 'app'

resource networkRg 'Microsoft.Resources/resourceGroups@2024-11-01' = {
  name: '${prefix}-rg'
  location: location
}

module app 'app.bicep' = {
  name: 'appDeployment'
  scope: networkRg
  params: {
    location: location
  }
}

output resourceGroupId string = networkRg.id

# how the file is run today
az deployment group create --resource-group rg-app --template-file main.bicep

param location string = resourceGroup().location

resource vnet 'Microsoft.Network/virtualNetworks@2025-04-01' = {
  name: 'app-vnet'
  location: location
  properties: {
    addressSpace: {
      addressPrefixes: [
        '10.10.0.0/16'
      ]
    }
    subnets: [
      {
        name: 'app-subnet'
        properties: {
          addressPrefix: '10.10.1.0/24'
        }
      }
    ]
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2025-04-01' = {
  name: 'app-nic'
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
          subnet: {
            id: vnet.properties.subnets[0].id
          }
        }
      }
    ]
  }
}

resource osdisk 'Microsoft.Compute/disks@2025-04-01' = {
  name: 'app-vm-osdisk'
  location: location
  sku: {
    name: 'Premium_LRS'
  }
  properties: {
    diskSizeGB: 127
    creationData: {
      createOption: 'Empty'
    }
  }
}

resource vm 'Microsoft.Compute/virtualMachines@2025-04-01' = {
  name: 'app-vm'
  location: location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D2s_v5'
    }
    storageProfile: {
      imageReference: {
        publisher: 'MicrosoftWindowsServer'
        offer: 'WindowsServer'
        sku: '2022-datacenter-azure-edition'
        version: 'latest'
      }
      osDisk: {
        createOption: 'Attach'
        managedDisk: {
          id: osdisk.id
        }
      }
    }
    osProfile: {
      computerName: 'app-vm'
      adminUsername: 'azureuser'
      adminPassword: 'S3cure-Passw0rd!'
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
          properties: {
            primary: true
          }
        }
      ]
    }
  }
}

targetScope = 'resourceGroup'

@description('Names of the virtual machines to create')
param hostnames array

@allowed(['Standard_D2s_v5', 'Standard_D4s_v5'])
param machineSize string = 'Standard_D2s_v5'

var location = resourceGroup().location
var production = deployment().name == 'prod'

resource vnet 'Microsoft.Network/virtualNetworks@2024-05-01' = {
  name: 'webVnet'
  location: location
  properties: {
    addressSpace: {
      addressPrefixes: ['10.10.0.0/16']
    }
  }
}

resource nics 'Microsoft.Network/networkInterfaces@2024-05-01' = [for (name, i) in hostnames: {
  name: 'nic-${name}'
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig'
        properties: {
          subnet: { id: vnet.id }
          privateIPAllocationMethod: 'Dynamic'
        }
      }
    ]
  }
}]

resource vms 'Microsoft.Compute/virtualMachines@2024-07-01' = [for (name, i) in hostnames: {
  name: name
  location: location
  properties: {
    hardwareProfile: {
      vmSize: machineSize
    }
    networkProfile: {
      networkInterfaces: [
        { id: nics[i].id }
      ]
    }
  }
}]

resource dataDisk 'Microsoft.Compute/disks@2024-04-01' = if (production) {
  name: 'webDataDisk'
  location: location
  sku: { name: 'Premium_LRS' }
  properties: { diskSizeGB: 128 }
}

module addons './addons.bicep' = {
  name: 'deployAddons'
  params: {
    targetVnetId: vnet.id
  }
}

output vmIds array = [for (name, i) in hostnames: vms[i].id]

targetScope = 'resourceGroup'

@description('Number of web instances to roll out')
param instanceCount int = 3

@allowed([
  'Standard_D2s_v5'
  'Standard_D4s_v5'
])
param vmSize string = 'Standard_D2s_v5'

@minLength(12)
param adminPassword string

@secure()
param dbConnectionString string

@minValue(1)
param monitorIntervalInSeconds int = 60

@maxLength(24)
param adminUsername string = 'azureuser'

param deployAvailabilitySet bool = true

resource webAvailabilitySet 'Microsoft.Compute/availabilitySets@2024-01-01' =
  if (deployAvailabilitySet) {
    name: 'web-aset-01'
    location: resourceGroup().location
    sku: {
      name: 'Aligned'
    }
  }

targetScope = 'resourceGroup'

param vmNames array = [
  'app-vm-01'
  'app-vm-02'
  'app-vm-03'
]

resource disks 'Microsoft.Compute/disks@2025-06-01' = [for name in vmNames: {
  name: '${name}-osdisk'
  location: resourceGroup().location
  sku: { name: 'Premium_LRS' }
  properties: { diskSizeGB: 128, createOption: 'Empty' }
}]

resource vms 'Microsoft.Compute/virtualMachines@2025-06-01' = [for name in vmNames: {
  name: name
  location: resourceGroup().location
  properties: {
    hardwareProfile: { vmSize: 'Standard_D2s_v3' }
    storageProfile: {
      imageReference: { publisher: 'MicrosoftWindowsServer', offer: 'WindowsServer', sku: '2022-datacenter', version: 'latest' }
      osDisk: { createOption: 'FromImage' }
    }
  }
}]
